<?php
$subs=subjects($pdo);$editId=(int)($_GET['edit']??0);$edit=null;$editValues=[];
if($editId){$s=$pdo->prepare('SELECT * FROM mahasiswa WHERE id=?');$s->execute([$editId]);$edit=$s->fetch();if($edit){$q=$pdo->prepare('SELECT mata_kuliah_id,nilai FROM nilai_mahasiswa WHERE mahasiswa_id=?');$q->execute([$editId]);foreach($q as $v)$editValues[(int)$v['mata_kuliah_id']]=$v['nilai'];}}
$q=trim((string)($_GET['q']??''));$angkatan=(int)($_GET['angkatan']??0);
$sql="SELECT m.*,COUNT(DISTINCT n.mata_kuliah_id) lengkap FROM mahasiswa m LEFT JOIN nilai_mahasiswa n ON n.mahasiswa_id=m.id WHERE 1=1";$params=[];
if($q!==''){$sql.=' AND m.kode_mahasiswa LIKE ?';$params[]="%$q%";}if($angkatan){$sql.=' AND m.angkatan=?';$params[]=$angkatan;}
$sql.=' GROUP BY m.id ORDER BY m.kode_mahasiswa';$st=$pdo->prepare($sql);$st->execute($params);$students=$st->fetchAll();
$years=$pdo->query('SELECT DISTINCT angkatan FROM mahasiswa ORDER BY angkatan DESC')->fetchAll(PDO::FETCH_COLUMN);
?>
