<form action="<?= APP_BASE ?>/process/mahasiswa-process.php" method="post" class="student-form"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>">
