<div class="form-actions"><a class="btn btn-outline" href="<?= url('mahasiswa') ?>">Batal</a><button class="btn btn-primary" type="submit">Simpan data</button></div></form></section>
<?php endif; ?>
<section class="panel"><div class="panel-heading"><div><h2>Daftar mahasiswa</h2><p><?= count($students) ?> data sesuai filter</p></div><form class="filter-form" method="get"><input type="hidden" name="page" value="mahasiswa"><input name="q" value="<?= e($q) ?>" placeholder="Cari kode mahasiswa"><select name="angkatan"><option value="0">Semua angkatan</option><?php foreach($years as $y): ?><option value="<?= (int)$y ?>" <?= $angkatan===(int)$y?'selected':'' ?>><?= (int)$y ?></option><?php endforeach; ?></select><button class="btn btn-outline" type="submit">Filter</button></form></div>
