<?php foreach($students as $i=>$s): $h=$pdo->prepare('SELECT label_kompetensi FROM hasil_clustering WHERE mahasiswa_id=? ORDER BY riwayat_clustering_id DESC LIMIT 1');$h->execute([$s['id']]);$label=$h->fetchColumn(); ?>
<tr><td><?= $i+1 ?></td><td><strong><?= e($s['kode_mahasiswa']) ?></strong></td><td><?= (int)$s['angkatan'] ?></td><td><span class="pill <?= (int)$s['lengkap']===count($subs)?'pill-success':'pill-warning' ?>"><?= (int)$s['lengkap'] ?>/<?= count($subs) ?> nilai</span></td><td><?= $label?e($label):'<span class="muted">Belum tersedia</span>' ?></td><td class="actions"><a class="action-link" href="<?= url('mahasiswa',['edit'=>$s['id']]) ?>">Edit</a><button class="action-link danger-link" type="button" data-confirm-form="delete-<?= (int)$s['id'] ?>">Hapus</button><form id="delete-<?= (int)$s['id'] ?>" hidden method="post" action="<?= APP_BASE ?>/process/mahasiswa-process.php"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"></form></td></tr>
<?php endforeach; if(!$students): ?><tr><td colspan="6"><div class="empty-inline">Data tidak ditemukan. Coba ubah filter atau tambahkan data baru.</div></td></tr><?php endif; ?></tbody></table></div>
